import { expect, test } from "@playwright/test";

const EMAIL = process.env.E2E_EMAIL!;
const PASSWORD = process.env.E2E_PASSWORD!;

test("diagnose checkout CTA", async ({ page }) => {
  test.setTimeout(180_000);

  const errors: string[] = [];
  page.on("console", (m) => m.type() === "error" && errors.push(m.text()));
  page.on("pageerror", (e) => errors.push(`pageerror: ${e.message}`));

  await page.goto("/sign-in");
  await page.locator('input[name="email"]').fill(EMAIL);
  await page.locator('input[name="password"]').fill(PASSWORD);
  await page.getByRole("button", { name: /sign in/i }).click();
  await page.waitForURL(/\/account/);

  // What does the CTA actually point at?
  await page.goto("/join");
  const cta = page.getByRole("link", { name: /choose supporter/i }).first();
  console.log("CTA href =", await cta.getAttribute("href"));

  // (a) client-side <Link> click
  await cta.click();
  await page.waitForTimeout(8000);
  console.log("after Link click, url =", page.url());
  console.log("console errors =", JSON.stringify(errors.slice(0, 5)));

  // (b) direct full-page navigation to the same route
  const href = (await cta.getAttribute("href")) ?? "/join/checkout?tier=supporter&cadence=monthly";
  const resp = await page.goto(href, { waitUntil: "domcontentloaded" }).catch((e) => {
    console.log("goto threw:", e.message);
    return null;
  });
  console.log("after direct goto, url =", page.url(), "| status =", resp?.status());

  expect(true).toBe(true);
});
